sp_DevolverEstoquePedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_DevolverEstoquePedido`(p_idPedido INT, p_idUsuario INT)\nBEGIN\n    DECLARE v_tipo_id INT;\n\n    SELECT idTipoMovimentacao INTO v_tipo_id\n    FROM TipoMovimentacao WHERE Nome = 'ENTRADA' LIMIT 1;\n\n    UPDATE Estoque e\n    INNER JOIN PedidoItem ip ON ip.idProduto = e.produto_id\n    INNER JOIN Pedido p ON p.idPedido = ip.idPedido AND p.idEmpresa = e.idEmpresa\n    SET e.QtdeAtual = e.QtdeAtual + ip.quantidade, e.dthAtualizacao = CURDATE()\n    WHERE ip.idPedido = p_idPedido;\n\n    INSERT INTO MovimentacaoEstoque (\n        estoque_id, usuario_id, tipoMovimentacao_id,\n        produto_id, dthMovimentacao, Qtde, Observacao, idEmpresa\n    )\n    SELECT\n        e.idEstoque, p_idUsuario, v_tipo_id,\n        ip.idProduto, CURDATE(), ip.quantidade,\n        CONCAT('Devolução automática ? pedido #', p_idPedido),\n        p.idEmpresa\n    FROM PedidoItem ip\n    INNER JOIN Pedido p ON p.idPedido = ip.idPedido\n    INNER JOIN Estoque e ON e.produto_id = ip.idProduto AND e.idEmpresa = p.idEmpresa\n    WHERE ip.idPedido = p_idPedido;\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
